package com.smarttraining.evaluation.dto;
import com.smarttraining.evaluation.entity.QuizAttempt; import java.time.LocalDateTime;
public class ScoreResponse { private Long attemptId;private Long quizId;private Long learnerId;private Integer score;private Integer totalPoints;private Boolean success;private LocalDateTime submittedAt; public ScoreResponse(){} public ScoreResponse(QuizAttempt a){attemptId=a.getId();quizId=a.getQuizId();learnerId=a.getLearnerId();score=a.getScore();totalPoints=a.getTotalPoints();success=a.getSuccess();submittedAt=a.getSubmittedAt();} public Long getAttemptId(){return attemptId;}public Long getQuizId(){return quizId;}public Long getLearnerId(){return learnerId;}public Integer getScore(){return score;}public Integer getTotalPoints(){return totalPoints;}public Boolean getSuccess(){return success;}public LocalDateTime getSubmittedAt(){return submittedAt;} }
